const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',layers:'<path d="m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 12l10 5 10-5"/>',book:'<path d="M12 5v16M3 3c5 0 9 2 9 2s4-2 9-2v16c-5 0-9 2-9 2s-4-2-9-2Z"/>',timer:'<circle cx="12" cy="14" r="8"/><path d="M12 10v4l3 2M9 2h6M12 2v4m6 1 2-2"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 3 5-8"/>',check:'<path d="m5 12 4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7Z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const main=document.querySelector('main');
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>${action}</div>`}
function home(){main.innerHTML=`
<section class="launch-hero"><div class="launch-copy"><p class="exam-label">ЕГЭ по информатике</p><h1>Большой балл.<br><span>Маленькими<br>шагами.</span></h1><p class="hero-description">Пойми идею. Напиши код. Реши задачу.<br>Уверенность приходит с практикой.</p><div class="hero-actions"><a href="#practice" class="button primary">К практике <span aria-hidden="true">↗</span></a><a href="#training" class="button secondary">${icon('timer')} Начать тренировку</a></div></div>
<div class="orbit-scene" aria-hidden="true"><div class="orbit-glow"></div><div class="orbit-ring ring-one"></div><div class="orbit-ring ring-two"></div><div class="orbit-ring ring-three"></div><div class="orbit-core"><span class="code-bracket">&lt;</span><span class="core-number">100</span><span class="code-bracket">&gt;</span></div><div class="orbit-chip chip-python">Python <span>↗</span></div><div class="orbit-chip chip-binary">0 1 0 1</div><div class="orbit-chip chip-check">${icon('check')} Я понял!</div><span class="orbit-spark spark-one">✦</span><span class="orbit-spark spark-two">✦</span></div></section>
<div class="learning-strip"><span><b>18</b> задач с разбором</span><span><b>6</b> конспектов</span><span><b>15</b> минут на тренировку</span><a href="#progress"><b id="home-solved">0<span>/18</span></b> решено <span aria-hidden="true">↗</span></a></div>
<section class="paths-section"><div class="section-heading"><h2>Сегодня — ещё на шаг ближе.</h2><p>Выбери, с чего начнёшь.</p></div><div class="path-grid">
<a class="path-card" href="#practice/logic"><span class="path-icon">01</span><h3>Логика<br>и числа</h3><p>Таблицы истинности и системы счисления.</p><span class="path-bottom">6 задач <span class="circle-arrow" aria-hidden="true">↗</span></span></a>
<a class="path-card" href="#practice/code"><span class="path-icon">&lt;/&gt;</span><h3>Алгоритмы<br>и Python</h3><p>Циклы, рекурсия и исполнители.</p><span class="path-bottom">6 задач <span class="circle-arrow" aria-hidden="true">↗</span></span></a>
<a class="path-card" href="#practice/data"><span class="path-icon">{ }</span><h3>Информация<br>и данные</h3><p>Кодирование, комбинаторика и сети.</p><span class="path-bottom">6 задач <span class="circle-arrow" aria-hidden="true">↗</span></span></a></div></section>
<section class="focus-banner"><div><p class="focus-label">Время для фокуса</p><h2>15 минут сегодня.<br>Больше уверенности завтра.</h2><p>5 задач, таймер и разбор результата.</p><a class="button" href="#training">Начать тренировку <span aria-hidden="true">↗</span></a></div><div class="focus-clock" aria-hidden="true"><span>15:00</span><div class="clock-dots"><i></i><i></i><i></i><i></i><i></i></div></div></section>
<section class="closing-section"><blockquote>«Сложно» — это пока.<br><span>«Я понял» — это практика.</span></blockquote><a href="#theory" class="theory-link">Нужно вспомнить теорию? <span>Открыть конспекты ↗</span></a></section>`;}
const tasks=[
{id:1,group:'logic',title:'Из десятичной в двоичную',level:'Базовый',time:2,text:'Переведи число 45 из десятичной системы счисления в двоичную. В ответе запиши только двоичные цифры, без основания системы.',answer:'101101',solution:'45 = 32 + 8 + 4 + 1 = 2⁵ + 2³ + 2² + 2⁰. Выпишем коэффициенты при степенях двойки от 5 до 0: 1 0 1 1 0 1. Ответ: 101101.'},
{id:2,group:'logic',title:'Когда импликация ложна',level:'Базовый',time:2,text:'Логическое выражение x → y ложно. Чему равны x и y? Запиши значения подряд, сначала x, затем y, без пробелов.',answer:'10',solution:'Импликация x → y равносильна ¬x ∨ y. Она ложна только тогда, когда условие истинно, а следствие ложно: x = 1, y = 0. Ответ: 10.'},
{id:3,group:'logic',title:'Целые числа и логика',level:'Базовый',time:3,text:'Для скольких целых чисел x истинно выражение (x > 5) ∧ (x < 12)?',answer:'6',solution:'Оба условия должны выполняться одновременно. Подходят целые числа 6, 7, 8, 9, 10 и 11. Всего 6 чисел.'},
{id:4,group:'logic',title:'Единицы в двоичной записи',level:'Базовый',time:3,text:'Сколько единиц содержится в двоичной записи числа 2¹⁰ + 2⁵ + 1?',answer:'3',solution:'Каждое слагаемое — отдельная степень двойки: 2¹⁰, 2⁵, 2⁰. Переносов между разрядами нет. В записи три единицы: 10000100001.'},
{id:5,group:'logic',title:'Число в системе с основанием 4',level:'Базовый',time:3,text:'Число 123 записано в системе счисления с основанием 4. Запиши это число в десятичной системе.',answer:'27',solution:'123₄ = 1 × 4² + 2 × 4¹ + 3 × 4⁰ = 16 + 8 + 3 = 27.'},
{id:6,group:'logic',title:'Логическое равенство',level:'Средний',time:4,text:'Для скольких наборов значений x, y, z выражение (x ∧ y) ∨ (¬x ∧ z) истинно? Каждая переменная принимает значение 0 или 1.',answer:'4',solution:'Если x = 1, выражение равно y: y = 1, а z любое — 2 набора. Если x = 0, выражение равно z: z = 1, а y любое — ещё 2 набора. Всего 4.'},
{id:7,group:'code',title:'Сумма в цикле',level:'Базовый',time:2,text:'Какое число выведет программа?',code:'s = 0\nfor i in range(1, 6):\n    s += i\nprint(s)',answer:'15',solution:'Правая граница range не входит в диапазон. Переменная i принимает значения 1, 2, 3, 4, 5. Сумма равна 15.'},
{id:8,group:'code',title:'Разбираемся с рекурсией',level:'Средний',time:4,text:'Алгоритм вычисления функции F(n) задан соотношениями:\nF(1) = 1;\nF(n) = F(n − 1) + 2n, если n > 1.\nНайди значение F(10).',answer:'109',solution:'F(10) = 1 + 2 × (2 + 3 + … + 10). Сумма чисел от 1 до 10 равна 55, поэтому F(10) = 1 + 2 × 54 = 109.'},
{id:9,group:'code',title:'Сколько раз выполнится цикл',level:'Базовый',time:3,text:'Какое значение переменной k выведет программа?',code:'n = 3\nk = 0\nwhile n < 100:\n    n *= 2\n    k += 1\nprint(k)',answer:'6',solution:'После каждой итерации n равно 6, 12, 24, 48, 96, 192. При n = 96 цикл ещё запускается. После шестой итерации условие ложно. k = 6.'},
{id:10,group:'code',title:'Обработка двоичной записи',level:'Базовый',time:3,text:'Какое число выведет программа?',code:"n = 29\ns = bin(n)[2:]\nprint(s.count('1'))",answer:'4',solution:'bin(29) возвращает строку 0b11101. Срез [2:] убирает префикс 0b. В строке 11101 четыре единицы.'},
{id:11,group:'code',title:'Программы для исполнителя',level:'Средний',time:5,text:'Исполнитель умеет выполнять две команды:\n1. Прибавить 1.\n2. Умножить на 2.\nСколько различных программ преобразуют число 2 в число 7? Разные последовательности команд считаются разными программами.',answer:'3',solution:'Пусть f(n) — число путей из 2 в n. f(2) = 1. Для нечётного n: f(n) = f(n − 1). Для чётного n > 2: f(n) = f(n − 1) + f(n / 2), причём f(1) = 0. Получаем f(3)=1, f(4)=2, f(5)=2, f(6)=3, f(7)=3.'},
{id:12,group:'code',title:'Отбор чисел в последовательности',level:'Средний',time:4,text:'Сколько элементов списка удовлетворяет условию программы?',code:'a = [12, 15, 20, 24, 30, 42, 55]\nk = 0\nfor x in a:\n    if x % 3 == 0 and x % 5 != 0:\n        k += 1\nprint(k)',answer:'3',solution:'Нужны числа, которые делятся на 3 и не делятся на 5. Это 12, 24 и 42. Числа 15 и 30 исключаются вторым условием. Ответ: 3.'},
{id:13,group:'data',title:'Сколько весит сообщение',level:'Базовый',time:3,text:'Алфавит содержит 32 символа. Все символы кодируются одинаковым минимально возможным числом бит. Сообщение содержит 120 символов. Каков его информационный объём в битах?',answer:'600',solution:'На один символ требуется log₂32 = 5 бит. Для сообщения из 120 символов: 120 × 5 = 600 бит.'},
{id:14,group:'data',title:'Объём растрового изображения',level:'Базовый',time:4,text:'Изображение размером 128 × 128 пикселей использует палитру из 16 цветов. Каждый пиксель кодируется одинаковым минимальным числом бит. Сжатия нет, заголовок и палитру не учитываем. Сколько байт занимает изображение?',answer:'8192',solution:'16 цветов требуют 4 бита на пиксель. Объём: 128 × 128 × 4 = 65 536 бит. Делим на 8: 8192 байта.'},
{id:15,group:'data',title:'Цифровая звукозапись',level:'Средний',time:4,text:'Стереозапись длится 10 секунд. Частота дискретизации — 8000 Гц, глубина кодирования — 16 бит на отсчёт каждого канала. Сжатия нет. Найди объём звуковых данных в байтах.',answer:'320000',solution:'В стереозаписи два канала. Объём в битах: 10 × 8000 × 16 × 2 = 2 560 000. В байтах: 2 560 000 / 8 = 320 000.'},
{id:16,group:'data',title:'Префиксный код',level:'Базовый',time:3,text:'Для букв используется двоичный код: A — 0, B — 10, C — 110, D — 111. Сколько бит содержит код слова BAD?',answer:'6',solution:'B кодируется двумя битами, A — одним, D — тремя. BAD → 10 0 111, всего 2 + 1 + 3 = 6 бит. Код удовлетворяет условию Фано: ни одно кодовое слово не является началом другого.'},
{id:17,group:'data',title:'Считаем слова',level:'Базовый',time:3,text:'Сколько различных пятибуквенных слов можно составить из букв А, Б, В, Г? Буквы могут повторяться. Словом считается любая последовательность из пяти букв.',answer:'1024',solution:'Для каждой из пяти позиций есть 4 независимых варианта. По правилу произведения: 4⁵ = 1024 слова.'},
{id:18,group:'data',title:'Адреса в подсети',level:'Средний',time:4,text:'Маска IPv4-подсети — 255.255.255.192. Сколько всего адресов содержит подсеть, включая адрес сети и широковещательный адрес?',answer:'64',solution:'192₁₀ = 11000000₂. Маска содержит 26 единиц и 6 нулей. Для адресов остаётся 6 бит, поэтому в подсети 2⁶ = 64 адреса. Вычитать два адреса не нужно: по условию они включены.'}
];
const groups={logic:'Логика и системы счисления',code:'Алгоритмы и Python',data:'Информация и данные'};
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
let storageOK=true;
let state={solved:[],attempts:0,correct:0,days:[],sessions:0};
try{const s=JSON.parse(localStorage.getItem('orbita-progress-v1'));if(s&&Array.isArray(s.solved)&&Array.isArray(s.days)&&[s.attempts,s.correct,s.sessions].every(Number.isFinite)){state={solved:[...new Set(s.solved.filter(id=>tasks.some(t=>t.id===id)))],days:s.days.filter(d=>/^\d{4}-\d{2}-\d{2}$/.test(d)),attempts:Math.max(0,s.attempts),correct:Math.max(0,Math.min(s.correct,s.attempts)),sessions:Math.max(0,s.sessions)}}}catch{storageOK=false}
function persist(){try{localStorage.setItem('orbita-progress-v1',JSON.stringify(state))}catch{storageOK=false;toast('Сохранение недоступно. Прогресс останется до закрытия страницы.')}}
function record(task,answer){const correct=answer.trim()===task.answer;state.attempts++;if(correct){state.correct++;if(!state.solved.includes(task.id))state.solved.push(task.id)}const day=dateKey();if(!state.days.includes(day))state.days.push(day);persist();return correct}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',4000)}
function updateHome(){const el=document.querySelector('#home-solved');if(el)el.innerHTML=state.solved.length+'<span>/18</span>'}
function setupHeroInteraction(){const art=document.querySelector('.hero-art');if(!art)return;let ax=0,ay=0;const move=(x,y)=>{if(document.documentElement.classList.contains('motion-paused')||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;art.style.setProperty('--rx',y+'deg');art.style.setProperty('--ry',x+'deg')};art.addEventListener('pointermove',e=>{const r=art.getBoundingClientRect();move((e.clientX-r.left-r.width/2)/r.width*24,-(e.clientY-r.top-r.height/2)/r.height*20)});art.addEventListener('pointerleave',()=>move(0,0));art.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')ax-=5;if(e.key==='ArrowRight')ax+=5;if(e.key==='ArrowUp')ay+=5;if(e.key==='ArrowDown')ay-=5;ax=Math.max(-25,Math.min(25,ax));ay=Math.max(-20,Math.min(20,ay));move(ax,ay)});}
let practiceFilter='all',practiceStatus='all';
function practice(group){if(group&&groups[group])practiceFilter=group;main.innerHTML=heading('Практика','18 задач с проверкой ответа и разбором.')+`<div class="filters" aria-label="Темы"><button class="filter ${practiceFilter==='all'?'active':''}" data-filter="all">Все темы</button>${Object.entries(groups).map(([key,title])=>`<button class="filter ${practiceFilter===key?'active':''}" data-filter="${key}">${title}</button>`).join('')}<label class="sr-label" for="status-filter">Статус:</label><select id="status-filter" class="filter"><option value="all">Все задачи</option><option value="new">Ещё не решены</option><option value="solved">Решены</option></select></div><div id="task-list"></div>`;document.querySelector('#status-filter').value=practiceStatus;drawTasks()}
function drawTasks(){const filtered=tasks.filter(t=>(practiceFilter==='all'||t.group===practiceFilter)&&(practiceStatus==='all'||(practiceStatus==='solved')===state.solved.includes(t.id)));document.querySelector('#task-list').innerHTML=filtered.length?`<div class="task-grid">${filtered.map(t=>`<article class="task-card"><div class="task-meta"><b>Задача ${String(t.id).padStart(2,'0')}</b><span>${state.solved.includes(t.id)?'✓ Решено':t.level}</span></div><h2>${t.title}</h2><p>${groups[t.group]}<br>≈ ${t.time} мин · авторская задача</p><button class="button secondary" data-task="${t.id}">${state.solved.includes(t.id)?'Решить ещё раз':'Решить задачу'} <span>↗</span></button></article>`).join('')}</div>`:'<div class="empty">Здесь пока нет задач с таким статусом.<br>Выбери другой фильтр или начни решать.</div>'}
const dialog=document.querySelector('#task-dialog');let currentTask=null,lastAnswer=null;
function taskBody(t){return `<div class="question"><h2 id="task-title">${t.title}</h2><div class="question-text">${escapeHTML(t.text)}</div>${t.code?`<pre><code>${escapeHTML(t.code)}</code></pre>`:''}</div>`}
function openTask(id){const t=tasks.find(t=>t.id===Number(id));if(!t)throw new Error('Задача не найдена');currentTask=t;lastAnswer=null;document.querySelector('#dialog-content').innerHTML=`<div class="dialog-top"><span>ЗАДАЧА ${String(t.id).padStart(2,'0')} · ${t.level} · ≈ ${t.time} мин</span><button class="icon-button" data-close aria-label="Закрыть задачу">×</button></div>${taskBody(t)}<form class="answer-form" id="practice-answer"><label for="answer">Твой ответ</label><input id="answer" name="answer" autocomplete="off" placeholder="Введи ответ" maxlength="40" required><button class="button" type="submit">Проверить <span>↗</span></button></form><div id="feedback" role="status"></div><details class="solution"><summary>Показать разбор</summary><p>${t.solution}</p></details>`;dialog.showModal();document.querySelector('#answer').focus();return {id:t.id,title:t.title}}
function submitPractice(value){if(!currentTask||!dialog.open)throw new Error('Сначала открой задачу');const answer=String(value).trim();if(!answer)throw new Error('Введи ответ');if(answer===lastAnswer)return {correct:answer===currentTask.answer,alreadyChecked:true};lastAnswer=answer;const correct=record(currentTask,answer);document.querySelector('#answer').value=answer;document.querySelector('#feedback').innerHTML=`<div class="feedback"><strong>${correct?'✓ Верно. Ещё один шаг вперёд!':'Пока не сходится.'}</strong><br>${correct?'Прогресс сохранён.':'Попробуй ещё раз или открой разбор.'}</div>`;if(correct)celebrate();return {id:currentTask.id,correct}}
dialog.addEventListener('close',()=>{currentTask=null;route(false)});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
const lessons={
logic:{title:'Логика без лишней магии',body:'<p>Начинай с порядка операций: отрицание, конъюнкция, дизъюнкция, импликация, эквивалентность. Скобки имеют приоритет.</p><h3>Четыре операции, которые нужно понимать</h3><ul><li><b>¬A — НЕ:</b> меняет 0 на 1 и наоборот.</li><li><b>A ∧ B — И:</b> истина, только если оба операнда истинны.</li><li><b>A ∨ B — ИЛИ:</b> истина, если истинен хотя бы один операнд.</li><li><b>A → B:</b> ложь только при A = 1 и B = 0.</li></ul><div class="formula">A → B ≡ ¬A ∨ B</div><h3>Как не потеряться в таблице истинности</h3><p>Для n переменных нужно 2ⁿ строк. Перебери наборы по порядку: 000, 001, 010… Вычисляй сложное выражение по частям и записывай промежуточные значения в отдельные столбцы.</p><h3>Законы де Моргана</h3><div class="formula">¬(A ∧ B) ≡ ¬A ∨ ¬B<br>¬(A ∨ B) ≡ ¬A ∧ ¬B</div><p>Когда переносишь отрицание внутрь скобок, меняй И на ИЛИ и отрицай каждый операнд.</p>',group:'logic'},
numbers:{title:'Системы счисления',body:'<p>В позиционной системе значение цифры зависит от её места. Крайний правый разряд — нулевой.</p><div class="formula">abcₚ = a · p² + b · p + c</div><h3>Из другой системы в десятичную</h3><p>Умножь каждую цифру на основание в степени номера разряда, затем сложи результаты. Например, 1011₂ = 8 + 0 + 2 + 1 = 11.</p><h3>Из десятичной в другую</h3><p>Дели число на основание, записывая остатки, пока частное не станет нулём. Прочитай остатки снизу вверх. Для нуля запись — 0.</p><pre>bin(45)[2:]     # \'101101\'\nint(\'123\', 4)  # 27\noct(64)[2:]     # \'100\'\nhex(255)[2:]    # \'ff\'</pre><h3>Полезная закономерность</h3><p>В двоичной записи числа 2ⁿ стоит единица и n нулей. Число 2ⁿ − 1 содержит n единиц. Следи за переносами: 2³ + 2³ = 2⁴.</p>',group:'logic'},
code:{title:'Python: уверенная база',body:'<p>Перед запуском программы попробуй пройти один-два шага вручную. Так легче заметить неверную границу цикла или условие.</p><h3>Деление и остаток</h3><pre>17 // 5  # 3 — целочисленное деление\n17 % 5   # 2 — остаток от деления\n2 ** 5   # 32 — возведение в степень</pre><h3>Границы range</h3><p>В range(start, stop, step) правая граница stop не включается. range(1, 6) даёт числа от 1 до 5. По умолчанию шаг равен 1.</p><pre>s = 0\nfor x in range(1, 6):\n    s += x\nprint(s)  # 15</pre><h3>Проверка делимости</h3><p>Условие x % d == 0 означает, что x делится на d без остатка. Для объединения условий используй and, or и not. Не путай присваивание = и сравнение ==.</p><h3>Контрольный список</h3><ul><li>Проверь включение крайних значений.</li><li>Обнуляй счётчики в нужном месте.</li><li>Проверь случай без подходящих элементов.</li><li>Используй маленький пример с известным ответом.</li></ul>',group:'code'},
recursion:{title:'Рекурсия и подсчёт программ',body:'<p>Рекурсия задаёт решение через более простой случай. У неё обязательно есть база — значение, которое вычисляется без нового вызова.</p><h3>Раскрывай от меньшего к большему</h3><p>Если F(1) = 1 и F(n) = F(n − 1) + 2n, то F(2) = 5, F(3) = 11. Для больших n часто проще цикл, а не глубокие рекурсивные вызовы.</p><pre>f = 1\nfor n in range(2, 11):\n    f += 2 * n\nprint(f)  # 109</pre><h3>Сколько программ ведёт к цели</h3><p>При командах «+1» и «×2» число путей к n равно сумме путей к возможным предыдущим значениям: n − 1 и n / 2, если n чётное. Этот подход работает здесь, потому что команды увеличивают положительное число.</p><div class="formula">f(n) = f(n − 1) + f(n / 2) <small>для чётного n</small></div><p>Задай один путь в начальную точку и ноль путей в недостижимые значения. Если задан обязательный промежуточный пункт, подсчитай пути до него и после него, затем перемножь результаты.</p>',group:'code'},
data:{title:'Информационный объём',body:'<p>Сначала приведи все величины к одним единицам. Большинство ошибок в этих задачах связано с битами, байтами и количеством каналов.</p><div class="formula">1 байт = 8 бит<br>1 Кбайт = 1024 байта</div><h3>Текст и равномерный код</h3><p>Для алфавита из N символов минимальная целая длина кода i определяется неравенством 2ⁱ ≥ N. Объём сообщения из K символов: I = K · i бит. Для 33 символов уже нужно 6 бит, а не 5.</p><h3>Изображения</h3><p>Без сжатия объём растрового изображения: ширина × высота × глубина цвета. Для палитры из 16 цветов достаточно 4 бит на пиксель. Заголовок и палитра учитываются отдельно, если это указано в условии.</p><h3>Звук</h3><div class="formula">I = f · t · b · k</div><p>f — частота дискретизации в герцах, t — время в секундах, b — глубина в битах, k — число каналов. Результат получится в битах. Для стерео k = 2.</p>',group:'data'},
networks:{title:'Сети и комбинаторика',body:'<h3>IPv4 и маска подсети</h3><p>IPv4-адрес содержит 32 бита. Единицы маски выделяют часть адреса сети, нули — часть узла. Адрес сети получается побитовым И адреса устройства и маски.</p><div class="formula">Адрес сети = IP AND маска</div><p>Маска /26 оставляет 32 − 26 = 6 бит. Всего в такой подсети 2⁶ = 64 адреса. Если спрашивают обычные доступные адреса узлов, обычно исключают адрес сети и широковещательный адрес. Всегда читай формулировку.</p><h3>Правило произведения</h3><p>Если для каждой из k позиций есть N независимых вариантов с повторениями, число последовательностей равно Nᵏ. Пять букв из алфавита из четырёх букв: 4⁵ = 1024.</p><h3>Если есть ограничения</h3><p>Разбей задачу на случаи или перебери варианты. Например, первая буква — А, остальные любые: 1 × 4⁴ = 256. При запрете повторений число вариантов на следующих позициях уменьшается.</p>',group:'data'}
};
function theory(key='logic'){if(!lessons[key])key='logic';const l=lessons[key];main.innerHTML=heading('Теория','Формулы, объяснения и примеры кода.')+`<div class="theory-layout"><div class="theory-menu" aria-label="Разделы теории">${Object.entries(lessons).map(([id,v])=>`<a class="filter ${key===id?'active':''}" href="#theory/${id}">${v.title}</a>`).join('')}</div><article class="theory-content"><h2>${l.title}</h2>${l.body}<a href="#practice/${l.group}" class="button dark">Закрепить на практике ↗</a></article></div>`}
let training=null,timer=null;
function trainingPage(){if(training?.finished){renderResults();return}if(training){renderTraining();return}main.innerHTML=heading('Тренировка','')+`<div class="training-panel"><section class="training-intro"><h2>Пять задач.<br>Три темы. Один фокус.</h2><p>Системы счисления, Python и работа с данными. Решай в любом порядке. Ответы и разборы откроются после завершения.</p><div class="training-tags"><span>5 задач</span><span>15 минут</span><span>Базовый уровень</span></div><button class="button" data-start>Начать тренировку <span>↗</span></button></section><p class="storage-notice">Учебная тренировка: 5 задач, не полный вариант ЕГЭ. Не обновляй страницу — текущие ответы не сохранятся.</p></div>`}
function startTraining(){if(training&&!training.finished)throw new Error('Тренировка уже идёт');training={ids:[1,7,13,3,17],answers:{},index:0,end:Date.now()+15*60*1000,finished:false};if(location.hash!=='#training')location.hash='training';renderTraining();clearInterval(timer);timer=setInterval(tick,1000);return {tasks:5,minutes:15}}
function renderTraining(){const t=tasks.find(t=>t.id===training.ids[training.index]);main.innerHTML=heading('Тренировка','')+`<div class="training-panel"><div class="training-toolbar"><div class="training-steps">${training.ids.map((id,i)=>`<button data-step="${i}" aria-label="Задача ${i+1}" class="${training.index===i?'active':''} ${training.answers[id]?'answered':''}">${i+1}</button>`).join('')}</div><strong id="countdown" aria-label="Оставшееся время"></strong><span>Ответов: ${Object.values(training.answers).filter(Boolean).length} / 5</span></div><section class="training-question">${taskBody(t)}<form class="answer-form" id="training-answer"><label for="training-value">Твой ответ</label><input id="training-value" autocomplete="off" maxlength="40" placeholder="Введи ответ" value="${escapeHTML(training.answers[t.id]||'')}"><button type="submit" class="button">${training.index===4?'Сохранить ответ':'Сохранить и дальше'} ↗</button></form></section><div class="training-actions"><button class="subtle-button" data-back ${training.index===0?'disabled':''}>← Назад</button><button class="subtle-button" data-finish>Завершить тренировку</button></div></div>`;tick()}
function tick(){if(!training||training.finished)return;if(Date.now()>=training.end){finishTraining();return}const el=document.querySelector('#countdown');if(el){const seconds=Math.max(0,Math.ceil((training.end-Date.now())/1000));el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}}
function captureTraining(){const input=document.querySelector('#training-value');if(input&&training&&!training.finished)training.answers[training.ids[training.index]]=input.value.trim()}
function finishTraining(){if(!training||training.finished)return;captureTraining();training.finished=true;clearInterval(timer);training.results=training.ids.map(id=>{const t=tasks.find(t=>t.id===id),answer=training.answers[id]||'';const correct=answer?record(t,answer):false;return {id,answer,correct}});state.sessions++;persist();if(location.hash.split('/')[0]==='#training')renderResults();else toast('Тренировка завершена. Результаты доступны в разделе «Тренировка».')}
function renderResults(){const correct=training.results.filter(r=>r.correct).length;main.innerHTML=heading('Тренировка завершена.','Ответы и разборы — ниже.')+`<div class="training-panel"><section class="white-card"><div class="result-score">${correct}<span style="color:var(--muted);font-size:30px;letter-spacing:-1px"> / 5</span></div><h2>${correct===5?'Отличная работа. Основы на месте.':'Теперь понятно, над чем поработать.'}</h2><p class="subtitle">Это результат мини-тренировки, а не прогноз балла ЕГЭ.</p>${training.results.map((r,i)=>{const t=tasks.find(t=>t.id===r.id);return `<details class="solution"><summary>${r.correct?'✓':'○'} ${i+1}. ${t.title}</summary><p>Твой ответ: <b>${r.answer?escapeHTML(r.answer):'не указан'}</b> · Правильный ответ: <b>${t.answer}</b></p><p>${t.solution}</p></details>`}).join('')}<div class="training-actions"><button class="button" data-start>Повторить тренировку ↗</button><a class="subtle-button" href="#practice">К практике</a></div></section></div>`}
function progressPage(){main.innerHTML=heading('Мой прогресс','')+`<div class="stats-row"><section class="stat"><div class="stat-top">Решено задач</div><div class="stat-value">${state.solved.length} <small>/ 18</small></div></section><section class="stat"><div class="stat-top">Точность ответов</div><div class="stat-value">${state.attempts?Math.round(state.correct/state.attempts*100)+'%':'—'}</div><div class="stat-caption">${state.correct} верных из ${state.attempts} попыток</div></section><section class="stat"><div class="stat-top">Завершено тренировок</div><div class="stat-value">${state.sessions}</div></section></div><div class="progress-table">${Object.entries(groups).map(([key,title])=>{const solved=tasks.filter(t=>t.group===key&&state.solved.includes(t.id)).length;return `<a class="progress-item" href="#practice/${key}"><strong>${title}</strong><div class="progress-track"><i style="width:${solved/6*100}%"></i></div><span>${solved} / 6 ↗</span></a>`}).join('')}</div>${state.attempts?'':'<div class="empty" style="margin-top:22px">Пока здесь чистый лист. Первая задача изменит это.<br><br><a class="button" href="#practice">Начать практику ↗</a></div>'}<p class="storage-notice">Дней с практикой: ${state.days.length}. Прогресс хранится в этом браузере.</p>`}
function route(scroll=true){captureTraining();const [page='home',sub]=location.hash.slice(1).split('/');const allowed=['home','practice','theory','training','progress'];const selected=allowed.includes(page)?page:'home';document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===selected);if(a.dataset.nav===selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('#crumb').textContent={home:'Главная',practice:'Практика',theory:'Теория',training:'Тренировка',progress:'Мой прогресс'}[selected];if(selected==='home'){home();updateHome()}if(selected==='practice')practice(sub);if(selected==='theory')theory(sub);if(selected==='training')trainingPage();if(selected==='progress')progressPage();if(!storageOK)main.insertAdjacentHTML('afterbegin','<div class="storage-error" role="status">Сохранение в браузере недоступно. Прогресс доступен до закрытия страницы.</div>');if(scroll){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.hasAttribute('data-close'))dialog.close();if(el.dataset.task)openTask(el.dataset.task);if(el.dataset.filter){practiceFilter=el.dataset.filter;practice()}if(el.hasAttribute('data-start'))startTraining();if(el.dataset.step!==undefined){captureTraining();training.index=Number(el.dataset.step);renderTraining()}if(el.hasAttribute('data-back')){captureTraining();training.index--;renderTraining()}if(el.hasAttribute('data-finish'))finishTraining()});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){practiceStatus=e.target.value;drawTasks()}});
document.addEventListener('submit',e=>{if(e.target.id==='practice-answer'){e.preventDefault();submitPractice(document.querySelector('#answer').value)}if(e.target.id==='training-answer'){e.preventDefault();captureTraining();if(training.index<4)training.index++;else toast('Ответ сохранён. Можно завершить тренировку.');renderTraining()}});
window.addEventListener('hashchange',()=>route());
window.addEventListener('beforeunload',e=>{if(training&&!training.finished){e.preventDefault();e.returnValue=''}});
function celebrate(){if(document.documentElement.classList.contains('motion-paused'))return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const layer=document.createElement('div');layer.className='celebration';layer.setAttribute('aria-hidden','true');for(let i=0;i<20;i++){const particle=document.createElement('i');const angle=Math.PI*2*i/20;particle.style.setProperty('--x',`${Math.cos(angle)*(90+Math.random()*130)}px`);particle.style.setProperty('--y',`${Math.sin(angle)*140+60}px`);particle.style.setProperty('--r',`${Math.random()*500}deg`);particle.style.animationDelay=`${i%4*25}ms`;layer.appendChild(particle)}(dialog.open?dialog:document.body).appendChild(layer);setTimeout(()=>layer.remove(),1100)}
const routeObserver=new MutationObserver(()=>{main.classList.remove('route-enter');requestAnimationFrame(()=>main.classList.add('route-enter'))});routeObserver.observe(main,{childList:true});
route(false);
const modelContext=document.modelContext;
if(modelContext?.registerTool){const lifecycle=new AbortController();const registry=[{name:'get_practice_progress',title:'Прогресс подготовки',description:'Read device-local progress and available practice tasks.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({solved:[...state.solved],attempts:state.attempts,tasks:tasks.map(({id,title,group})=>({id,title,group}))})},{name:'open_practice_task',title:'Открыть учебную задачу',description:'Open a practice task in the visible dialog without submitting an answer.',inputSchema:{type:'object',properties:{id:{type:'integer',minimum:1,maximum:18}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Number.isInteger(input.id)||!tasks.some(t=>t.id===input.id))throw new Error('Неизвестная задача');if(dialog.open)throw new Error('Сначала закрой текущую задачу');return openTask(input.id)}}];for(const tool of registry){try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}

let motionEnabled=!window.matchMedia('(prefers-reduced-motion: reduce)').matches;
try{if(localStorage.getItem('pro100code-motion')==='off')motionEnabled=false}catch{}
function applyMotion(){document.documentElement.classList.toggle('motion-paused',!motionEnabled);const button=document.querySelector('#motion-toggle');button.setAttribute('aria-pressed',String(motionEnabled));button.setAttribute('aria-label',motionEnabled?'Анимация включена. Выключить':'Анимация выключена. Включить')}
document.querySelector('#motion-toggle').addEventListener('click',()=>{motionEnabled=!motionEnabled;applyMotion();try{localStorage.setItem('pro100code-motion',motionEnabled?'on':'off')}catch{} });
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus()});
applyMotion();

